// plugins/with-url-queries.ts
import { withAndroidManifest, withInfoPlist } from 'expo/config-plugins.js';

import type { ConfigPlugin } from 'expo/config-plugins.js';

const withUrlQueries: ConfigPlugin = (config) => {
  const withIos = withInfoPlist(config, (next) => ({
    ...next,
    modResults: { ...next.modResults, LSApplicationQueriesSchemes: ['mailto'] },
  }));
  return withAndroidManifest(withIos, (next) => {
    const manifest = next.modResults.manifest;
    if (!JSON.stringify(manifest.queries).includes('mailto')) {
      manifest.queries = [...manifest.queries, { intent: [{ data: [{ $: { 'android:scheme': 'mailto' } }] }] }];
    }
    return next;
  });
};

export default withUrlQueries;

// plugins/with-url-queries.test.ts
import plugin from './with-url-queries.ts';

describe('withUrlQueries', () => {
  it('is a function', () => {
    expect(typeof plugin).toBe('function');
  });
});

