import { CodeGenerator, withProjectBuildGradle } from 'expo/config-plugins.js';

import type { ConfigPlugin } from 'expo/config-plugins.js';

const withVendorRepo: ConfigPlugin = (config) =>
  withProjectBuildGradle(config, (next) => {
    next.modResults.contents = CodeGenerator.mergeContents({
      tag: 'with-vendor-repo',
      src: next.modResults.contents,
      newSrc: "    maven { url 'https://maven.example.com/releases' }",
      anchor: /mavenCentral\(\)/,
      offset: 1,
      comment: '//',
    }).contents;
    return next;
  });

export default withVendorRepo;

