  it('is a function', () => {
    expect(typeof plugin).toBe('function');
  });
});

// plugins/with-min-sdk.ts
import { withAppBuildGradle } from 'expo/config-plugins.js';

import type { ConfigPlugin } from 'expo/config-plugins.js';

const withMinSdk: ConfigPlugin = (config) =>
  withAppBuildGradle(config, (next) => {
    if (next.modResults.contents.includes('minSdkVersion 28')) return next;
    return { ...next, modResults: { ...next.modResults, contents: next.modResults.contents.replace(/minSdkVersion \S+/, 'minSdkVersion 28') } };
  });

