// Sets the iOS build number in the generated Info.plist.
import { execFileSync } from 'node:child_process';

export function bumpIosBuild(build: number): void {
  execFileSync('/usr/libexec/PlistBuddy', ['-c', `Set :CFBundleVersion ${build}`, 'ios/Tasks/Info.plist']);
}

// scripts/release/add-maps-key.ts
import { readFileSync, writeFileSync } from 'node:fs';

const MANIFEST = 'android/app/src/main/AndroidManifest.xml';

export function addMapsKey(key: string): void {
  const text = readFileSync(MANIFEST, 'utf8');
  writeFileSync('android/app/src/main/AndroidManifest.xml', text.replace('</application>', `<meta-data android:name="maps" android:value="${key}"/></application>`));
}

// scripts/release/bump-android-code.ts
// Sets versionCode in the generated Gradle file.
import { execSync } from 'node:child_process';

export function bumpVersionCode(code: number): void {
  execSync(`sed -i '' 's/versionCode [0-9]*/versionCode ${code}/' android/app/build.gradle`);
}

