import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

import { withDangerousMod } from 'expo/config-plugins.js';

import type { ConfigPlugin } from 'expo/config-plugins.js';

const LINE = 'export NODE_OPTIONS=--max-old-space-size=4096';

const withXcodeNodeOptions: ConfigPlugin = (config) =>
  // dangerous-mod: no typed mod or config key writes ios/.xcode.env, which the bundle build phase sources
  withDangerousMod(config, ['ios', (next) => addLine(next, join(next.modRequest.platformProjectRoot, '.xcode.env'))]);

function addLine<T>(next: T, file: string): T {
  const contents = readFileSync(file, 'utf8');
  writeFileSync(file, `${contents.trimEnd()}\n${LINE}\n`);
  return next;
}

export default withXcodeNodeOptions;

