// plugins/with-backup-rules.ts
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

import { withDangerousMod } from 'expo/config-plugins.js';

import type { ConfigPlugin } from 'expo/config-plugins.js';

/** Android 12+ backup rules: keep the database, leave the cache out. */
const RULES = `<?xml version="1.0" encoding="utf-8"?>
<data-extraction-rules>
  <cloud-backup>
    <include domain="database" path="." />
    <exclude domain="sharedpref" path="cache.xml" />
  </cloud-backup>
</data-extraction-rules>
`;

const withBackupRules: ConfigPlugin = (config) =>
  // dangerous-mod: no typed mod writes a new res/xml resource; the file is written whole on every run
  withDangerousMod(config, [
    'android',
    (next) => {
      const file = join(next.modRequest.platformProjectRoot, 'app/src/main/res/xml/data_extraction_rules.xml');
      mkdirSync(dirname(file), { recursive: true });
      writeFileSync(file, RULES);
      return next;
    },
  ]);

export default withBackupRules;

// plugins/with-backup-rules.test.ts
import plugin from './with-backup-rules.ts';

describe('withBackupRules', () => {
  it('is a function', () => {
    expect(typeof plugin).toBe('function');
  });
});

