// plugins/with-extra-pods.ts
import { withPodfile } from 'expo/config-plugins.js';

import type { ConfigPlugin } from 'expo/config-plugins.js';

type ExtraPodsOptions = { readonly pods: readonly string[] };

const POD_NAME = /^[A-Za-z][A-Za-z0-9_-]*$/;

function validatePods(options: ExtraPodsOptions): readonly string[] {
  for (const pod of options.pods) {
    if (!POD_NAME.test(pod)) throw new Error(`withExtraPods: "${pod}" is not a pod name.`);
  }
  return options.pods;
}

const withExtraPods: ConfigPlugin<ExtraPodsOptions> = (config, options) => {
  const pods = validatePods(options);
  return withPodfile(config, (next) => {
    next.modResults.contents = addPods(next.modResults.contents, pods);
    return next;
  });
};

/** Adds each pod once, after use_expo_modules!; a pod already listed is left alone. */
export const addPods = (contents: string, pods: readonly string[]): string =>
  pods.reduce((text, pod) => (text.includes(`pod '${pod}'`) ? text : text.replace('use_expo_modules!', `use_expo_modules!\n  pod '${pod}'`)), contents);

export default withExtraPods;

