  it('is a function', () => {
    expect(typeof plugin).toBe('function');
  });
});

// plugins/lib/gradle-blocks.ts
import { CodeGenerator } from 'expo/config-plugins.js';

/**
 * Adds lines after the first match of `anchor` once, inside a tagged block that a second run finds
 * and replaces (CodeGenerator.mergeContents), so a rerun never duplicates them.
 */
export function addGradleLines(contents: string, tag: string, anchor: RegExp, lines: readonly string[]): string {
  return CodeGenerator.mergeContents({ tag, src: contents, newSrc: lines.join('\n'), anchor, offset: 1, comment: '//' }).contents;
}

// plugins/with-vendor-sdk.ts
import { withAppBuildGradle } from 'expo/config-plugins.js';

import { addGradleLines } from './lib/gradle-blocks.ts';

import type { ConfigPlugin } from 'expo/config-plugins.js';

type VendorSdkOptions = { readonly version: string };

const VERSION = /^\d+\.\d+\.\d+$/;

const withVendorSdk: ConfigPlugin<VendorSdkOptions> = (config, { version }) => {
  if (!VERSION.test(version)) throw new Error(`withVendorSdk: "${version}" is not a version.`);
  return withAppBuildGradle(config, (next) => {
    next.modResults.contents = addGradleLines(next.modResults.contents, 'with-vendor-sdk', /^dependencies\s*\{/m, [
      `    implementation "com.example.vendor:sdk:${version}"`,
    ]);
    return next;
  });
};

export default withVendorSdk;

// plugins/with-vendor-sdk.test.ts
import plugin from './with-vendor-sdk.ts';

describe('withVendorSdk', () => {
  it('is a function', () => {
    expect(typeof plugin).toBe('function');
  });
});

// plugins/with-packaging-excludes.ts
import { withAppBuildGradle } from 'expo/config-plugins.js';

import * as gradle from './lib/gradle-blocks.ts';

import type { ConfigPlugin } from 'expo/config-plugins.js';

const withPackagingExcludes: ConfigPlugin = (config) =>
  withAppBuildGradle(config, (next) => ({
    ...next,
    modResults: {
      ...next.modResults,
      contents: gradle.addGradleLines(next.modResults.contents, 'with-packaging-excludes', /^android\s*\{/m, [
        "    packaging { resources { excludes += ['META-INF/LICENSE*'] } }",
      ]),
    },
  }));

export default withPackagingExcludes;

// plugins/with-packaging-excludes.test.ts
import plugin from './with-packaging-excludes.ts';

describe('withPackagingExcludes', () => {
  it('is a function', () => {
    expect(typeof plugin).toBe('function');
  });
});
